new_incoming_sms.afterResponse:
// Like the original: the first check notes the newest message, and later checks page back to it and keep the inbound ones.
const KEY = '_new_incoming_sms_trigger';
if (!(KEY in memory)) { memory[KEY] = {lastMessageId: response.messages.length === 0 ? null : response.messages[0].sid}; return []; }
const last = memory[KEY], fresh = [];
let page = response, first;
while (page) {
  const messages = page.messages;
  if (!first && messages.length > 0) first = messages[0].sid;
  let next = page.next_page_uri;
  for (const message of messages) {
    if (message.sid === last?.lastMessageId) { next = null; break; }
    if (message.direction === 'inbound') fresh.push(message);
  }
  page = next ? call({method: 'GET', url: 'https://api.twilio.com' + next}) : null;
}
memory[KEY] = {lastMessageId: first ?? last.lastMessageId};
return fresh;

new_phone_number.beforeRequest:
// Like the original: a page of 10 on the first check.
if (!inputs.lastPollTime) request.query.PageSize = '10';
return request;

new_phone_number.afterResponse:
// Like the original: pages until an item is not newer than the last check, and only the first page on the first check.
const since = Number(inputs.lastPollTime) || 0, items = [];
let page = response;
while (true) {
  let older = false;
  for (const item of page.incoming_phone_numbers || []) {
    if (new Date(item.date_created).getTime() <= since) { older = true; break; }
    items.push(item);
  }
  if (older || !since || !page.next_page_uri) break;
  page = call({method: 'GET', url: 'https://api.twilio.com' + page.next_page_uri});
}
return items;

